import { build } from "esbuild";
import { writeFile } from "node:fs/promises";
const result = await build({
  entryPoints: ["server/webcodecs-client.ts"],
  bundle: true,
  write: false,
  platform: "browser",
  format: "iife",
  minify: true,
  legalComments: "inline",
  target: "es2022",
});
await writeFile(
  "server/webcodecs-source.generated.ts",
  "// Generated by scripts/prepare-media.mjs; retains dependency licenses.\nexport const webCodecsSource = " +
    JSON.stringify(result.outputFiles[0].text) +
    ";\n",
);
